// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/orders/mine", wrapper.ListMyOrders)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/orders/{id}", wrapper.GetMyOrder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/orders/{id}/invoice", wrapper.GetOrderInvoice)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/orders/{id}/returns", wrapper.RequestReturn)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/orders", wrapper.ListOrders)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/orders/{id}", wrapper.GetOrder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/orders/{id}/cancel", wrapper.CancelOrder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/orders/{id}/package", wrapper.PackageOrder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/orders/{id}/refund", wrapper.RefundOrder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/returns", wrapper.ListReturns)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/returns/{id}/accept", wrapper.AcceptReturn)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/returns/{id}/reject", wrapper.RejectReturn)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/orders", wrapper.CreateOrder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/internal/orders/{id}", wrapper.GetInternalOrder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/internal/orders/{id}/guest-access", wrapper.MintGuestAccess)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/internal/purchases", wrapper.FindPurchase)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/internal/customer-orders", wrapper.ListCustomerOrders)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/orders/{id}/confirm", wrapper.ConfirmOrder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/orders/{id}/abandon", wrapper.AbandonOrder)
	})

	return r
}

