// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListOrders List the shop's orders, newest first
	// (GET /admin/orders)
	ListOrders(ctx context.Context, request ListOrdersRequestObject) (ListOrdersResponseObject, error)
	// GetOrder Get an order with its status history
	// (GET /admin/orders/{id})
	GetOrder(ctx context.Context, request GetOrderRequestObject) (GetOrderResponseObject, error)
	// CancelOrder Cancel a placed order and refund its payment
	// (POST /admin/orders/{id}/cancel)
	CancelOrder(ctx context.Context, request CancelOrderRequestObject) (CancelOrderResponseObject, error)
	// PackageOrder Mark a received order packaged and book its shipment
	// (POST /admin/orders/{id}/package)
	PackageOrder(ctx context.Context, request PackageOrderRequestObject) (PackageOrderResponseObject, error)
	// RefundOrder Refund part of a placed order
	// (POST /admin/orders/{id}/refund)
	RefundOrder(ctx context.Context, request RefundOrderRequestObject) (RefundOrderResponseObject, error)
	// ListReturns List the shop's returns, newest first
	// (GET /admin/returns)
	ListReturns(ctx context.Context, request ListReturnsRequestObject) (ListReturnsResponseObject, error)
	// AcceptReturn Accept a return and refund it
	// (POST /admin/returns/{id}/accept)
	AcceptReturn(ctx context.Context, request AcceptReturnRequestObject) (AcceptReturnResponseObject, error)
	// RejectReturn Reject a return
	// (POST /admin/returns/{id}/reject)
	RejectReturn(ctx context.Context, request RejectReturnRequestObject) (RejectReturnResponseObject, error)
	// ListCustomerOrders List a customer's orders for GDPR deletion
	// (GET /internal/customer-orders)
	ListCustomerOrders(ctx context.Context, request ListCustomerOrdersRequestObject) (ListCustomerOrdersResponseObject, error)
	// CreateOrder Create a pending order
	// (POST /internal/orders)
	CreateOrder(ctx context.Context, request CreateOrderRequestObject) (CreateOrderResponseObject, error)
	// GetInternalOrder Get an order, whatever its status
	// (GET /internal/orders/{id})
	GetInternalOrder(ctx context.Context, request GetInternalOrderRequestObject) (GetInternalOrderResponseObject, error)
	// AbandonOrder Abandon a pending order
	// (POST /internal/orders/{id}/abandon)
	AbandonOrder(ctx context.Context, request AbandonOrderRequestObject) (AbandonOrderResponseObject, error)
	// ConfirmOrder Confirm a paid order
	// (POST /internal/orders/{id}/confirm)
	ConfirmOrder(ctx context.Context, request ConfirmOrderRequestObject) (ConfirmOrderResponseObject, error)
	// MintGuestAccess Mint a guest order access token
	// (GET /internal/orders/{id}/guest-access)
	MintGuestAccess(ctx context.Context, request MintGuestAccessRequestObject) (MintGuestAccessResponseObject, error)
	// FindPurchase Find a customer's purchase of a product
	// (GET /internal/purchases)
	FindPurchase(ctx context.Context, request FindPurchaseRequestObject) (FindPurchaseResponseObject, error)
	// ListMyOrders List my orders, newest first
	// (GET /orders/mine)
	ListMyOrders(ctx context.Context, request ListMyOrdersRequestObject) (ListMyOrdersResponseObject, error)
	// GetMyOrder Get one of my orders
	// (GET /orders/{id})
	GetMyOrder(ctx context.Context, request GetMyOrderRequestObject) (GetMyOrderResponseObject, error)
	// GetOrderInvoice Download the order invoice PDF
	// (GET /orders/{id}/invoice)
	GetOrderInvoice(ctx context.Context, request GetOrderInvoiceRequestObject) (GetOrderInvoiceResponseObject, error)
	// RequestReturn Ask to return delivered items
	// (POST /orders/{id}/returns)
	RequestReturn(ctx context.Context, request RequestReturnRequestObject) (RequestReturnResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

